#!/usr/bin/env python3
"""Embed the approved 48px launcher masks without changing their pixels."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
SOURCES = ROOT / "firmware/assets/menu_icons"
HEADER = ROOT / "firmware/assets/hackylens_menu_icons_1bpp.h"


def generated_header() -> str:
    manifest = json.loads((SOURCES / "manifest.json").read_text(encoding="utf-8"))
    lines = [
        "/* Approved V2 launcher glyphs. Generated by tools/make_menu_icons.py. */",
        "#ifndef HK_MENU_ICONS_1BPP_H",
        "#define HK_MENU_ICONS_1BPP_H",
        "#include <stdint.h>",
        "#define HK_MENU_ICON_SIZE 48U",
        "#define HK_MENU_ICON_ROW_BYTES 6U",
        "#define HK_MENU_ICON_BYTES 288U",
        "",
    ]
    for app_id, checksum in manifest["sha256"].items():
        data = (SOURCES / f"{app_id}.1bpp").read_bytes()
        if len(data) != 288 or hashlib.sha256(data).hexdigest() != checksum:
            raise ValueError(f"approved mask checksum/size mismatch: {app_id}")
        symbol = app_id.replace("-", "_")
        lines.append(f"static const uint8_t hk_menu_icon_{symbol}[HK_MENU_ICON_BYTES] = {{")
        for offset in range(0, len(data), 12):
            lines.append("    " + ", ".join(f"0x{value:02x}" for value in data[offset:offset + 12]) + ",")
        lines.extend(["};", ""])
    lines.extend(["#endif", ""])
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if the embedded masks are stale")
    args = parser.parse_args()
    expected = generated_header()
    if args.check:
        if not HEADER.is_file() or HEADER.read_text(encoding="utf-8") != expected:
            print("[FAIL] launcher assets are stale; run python tools/make_menu_icons.py")
            return 1
        print("[OK] all 12 launcher assets match the approved V2 masks")
    else:
        HEADER.write_text(expected, encoding="utf-8", newline="\n")
        print(f"[OK] {HEADER}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
